import React from 'react';

import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';

import { getDivIcon } from '@apps/Routes/@helpers/leaflet.helper';
import {
  mapWorkoutTrackMarkupToAddDto,
  mapWorkoutTrackMarkupToUpdateDTO,
} from '@apps/Workouts/@mappers/workoutTrackMarkup.mapper';
import {
  addWorkoutTrackMarkup,
  deleteWorkoutTrackMarkup,
  getWorkoutTrackMarkup,
  updateWorkoutTrackMarkup,
} from '@apps/Workouts/@services/workoutTrackMarkup.service';
import { IWorkoutFull } from '@apps/Workouts/@types/workouts.types';
import { IWorkoutTrackMarkup } from '@apps/Workouts/@types/workoutTrackMarkup.types';
import { AuthContext } from '@contexts/AuthContext';
import { getDistanceBetweenPointsInMeters, getDistanceByCoordsInMeters } from '@helpers/gpsHelper';
import { getDefaultTileLayer, getMap, setDefaultMapView } from '@helpers/leafletHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import { confirmModal } from '@ui-kit/Modal';

import { editWorkoutTrackMarkupInModalAsync } from './components/WorkoutTrackMarkupEditModal';
import WorkoutTrackMarkupItem from './components/WorkoutTrackMarkupItem';
import WorkoutTrackMarkupSelected from './components/WorkoutTrackMarkupSelected';
import WorkoutTrackMarkupTable from './components/WorkoutTrackMarkupTable';
import styles from './styles.module.less';

interface IWorkoutMarkupEditProps {
  workout: IWorkoutFull;
}

const WorkoutMarkupEdit: React.FC<IWorkoutMarkupEditProps> = ({ workout }) => {
  const mapContainerRef = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);

  const authContext = React.useContext(AuthContext);

  const trackPolyline = React.useRef<L.Polyline>(new L.Polyline([], {}));
  const activeMarkupPolyline = React.useRef<L.Polyline>(
    new L.Polyline([], { color: 'red', opacity: 0.4 }),
  );
  const selectedPolyline = React.useRef<L.Polyline>(
    new L.Polyline([], { color: 'violet', opacity: 0.8 }),
  );
  const activePoint = React.useRef<L.Marker>(new L.Marker([0, 0], { icon: getDivIcon() }));

  const listRef = React.useRef<HTMLTableSectionElement>(null);
  const rangeRef = React.useRef<HTMLInputElement>(null);

  const [selectedIndexes, setSelectedIndexes] = React.useState<number[]>([]);
  const [currentMarkup, setCurrentMarkup] = React.useState<IWorkoutTrackMarkup | null>(null);

  const [markups, setMarkups] = React.useState<IWorkoutTrackMarkup[]>([]);

  const indexMarkupsMap = React.useMemo(() => {
    return workout.track.reduce<{ [trackPointIndex: number]: IWorkoutTrackMarkup }>((acc, t, i) => {
      const targetMarkup = markups.find((x) => t.date >= x.utcD1 && t.date <= x.utcD2);
      if (targetMarkup) {
        acc[i] = targetMarkup;
      }

      return acc;
    }, {});
  }, [markups, workout.track]);

  React.useEffect(() => {
    if (!mapContainerRef.current) return;
    mapRef.current = getMap(mapContainerRef.current);

    getDefaultTileLayer().addTo(mapRef.current);
    setDefaultMapView(mapRef.current);

    trackPolyline.current.addTo(mapRef.current);
    activeMarkupPolyline.current.addTo(mapRef.current);
    activePoint.current.addTo(mapRef.current);
    selectedPolyline.current.addTo(mapRef.current);
  }, []);

  React.useEffect(() => {
    getWorkoutTrackMarkup(workout.id_workout_track).then(setMarkups);
  }, [workout.id_workout_track]);

  React.useEffect(() => {
    trackPolyline.current.setLatLngs(workout.track.map((x) => x.point));
    mapRef.current?.fitBounds(trackPolyline.current.getBounds());
  }, [workout.track]);

  const total = React.useMemo(() => {
    const distance = getDistanceByCoordsInMeters(
      workout.track.map((x) => x.point as [number, number]),
    );
    const duration =
      (workout.track[workout.track.length - 1].date.getTime() - workout.track[0].date.getTime()) /
      1000;

    const maxSpeed = Math.max(
      ...workout.track.map((trackItem, i, allPoints) => {
        if (i === 0) return 0;
        const dist = getDistanceBetweenPointsInMeters(
          allPoints[i - 1].point as [number, number],
          trackItem.point as [number, number],
        );
        const secs = (trackItem.date.getTime() - allPoints[i - 1].date.getTime()) / 1000;

        const speed = dist / secs;

        return speed;
      }),
    );

    return {
      distance,
      duration,
      speed: distance / duration,
      maxSpeed,
    };
  }, [workout.track]);

  React.useEffect(() => {
    if (!selectedIndexes.length) {
      selectedPolyline.current.setLatLngs([]);
      return;
    }
    selectedPolyline.current.setLatLngs(
      workout.track.map((x) => x.point).filter((_, i) => selectedIndexes.includes(i)),
    );
    mapRef.current?.fitBounds(selectedPolyline.current.getBounds());
  }, [selectedIndexes, workout.track]);

  React.useEffect(() => {
    window.requestIdleCallback(() => {
      if (location.hash.length > 1) {
        const num = +location.hash.substring(1);
        Number.isFinite(num) && scrollToPointByIndex(num);
      }
    });
  }, []);

  let distInc = 0;

  const scrollToPointByIndex = (i: number) => {
    if (!listRef.current) return;
    const el = listRef.current.childNodes[i] as HTMLElement;
    if (!el) return;
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-expect-error
    el.scrollIntoView({ block: 'center', container: 'nearest' });
    const existingActive = listRef.current.querySelector(`.${styles.active}`);
    existingActive && existingActive.classList.remove(styles.active);
    el.classList.add(styles.active);
    if (rangeRef.current) rangeRef.current.value = i.toString();
    location.hash = `#${i}`;
  };

  const handleSaveNew = async (data: Partial<IWorkoutTrackMarkup>) => {
    if (!authContext.user) return;

    const up = await editWorkoutTrackMarkupInModalAsync(
      {
        id: 0,
        id_workout_track: workout.id_workout_track,
        created_at: new Date(),
        updated_at: null,
        author: authContext.user,
        name: '',
        isBreak: true,
        utcD1: workout.track[selectedIndexes[0]].date,
        utcD2: workout.track[selectedIndexes[selectedIndexes.length - 1]].date,
        ...data,
      },
      `${data.id ? 'Редактировать' : 'Добавить'} ${data.isBreak ? 'привал' : 'участок'}`,
    );

    const dataForAdd = mapWorkoutTrackMarkupToAddDto(up, workout.id_workout_track);
    const id = await addWorkoutTrackMarkup(dataForAdd);
    setMarkups((cur) => [...cur, { ...up, id }]);
    notificationHelper.success('Сохранено');

    setSelectedIndexes([]);
  };

  const handleSaveExist = async () => {
    if (!currentMarkup) return;
    const up = await editWorkoutTrackMarkupInModalAsync(
      {
        ...currentMarkup,
        utcD1: workout.track[selectedIndexes[0]].date,
        utcD2: workout.track[selectedIndexes[selectedIndexes.length - 1]].date,
        updated_at: new Date(),
      },
      `Редактировать ${currentMarkup.isBreak ? 'привал' : 'участок'}`,
    );
    const dataForUpdate = mapWorkoutTrackMarkupToUpdateDTO(up);
    await updateWorkoutTrackMarkup(dataForUpdate);
    setMarkups((cur) => cur.map((x) => (x.id === up.id ? up : x)));
    notificationHelper.success('Данные обновлены');
    setSelectedIndexes([]);
    setCurrentMarkup(null);
    activeMarkupPolyline.current.setLatLngs([]);
  };

  const handleEdit = async (markup: IWorkoutTrackMarkup) => {
    setCurrentMarkup(markup);
    const indexes = workout.track.reduce<number[]>((acc, x, i) => {
      if (x.date >= markup.utcD1 && x.date <= markup.utcD2) {
        acc.push(i);
      }

      return acc;
    }, []);
    setSelectedIndexes(indexes);
    scrollToPointByIndex(indexes[0]);
  };

  const changeSelection = (action: 'addStart' | 'removeStart' | 'addEnd' | 'removeEnd') => {
    setSelectedIndexes((cur) => {
      let newIndex = 0;

      if (action === 'addStart') newIndex = cur[0] - 1;
      if (action === 'addEnd') newIndex = cur[cur.length - 1] + 1;

      if (newIndex < 0) {
        notificationHelper.warn('Достигнуто начало трека');
        return cur;
      }

      if (newIndex > workout.track.length - 1) {
        notificationHelper.warn('Достигнуто конец трека');
        return cur;
      }

      if (indexMarkupsMap[newIndex] && currentMarkup?.id !== indexMarkupsMap[newIndex].id) {
        notificationHelper.warn(`Пересечение с "${indexMarkupsMap[newIndex].name}"`);
        return cur;
      }

      if (action === 'addStart') return [newIndex, ...cur];
      if (action === 'addEnd') return [...cur, newIndex];
      if (action === 'removeStart') return cur.slice(1, cur.length);
      if (action === 'removeEnd') return cur.slice(0, cur.length - 1);

      return cur;
    });
    scrollToPointByIndex(
      action === 'addEnd' || action === 'removeEnd'
        ? selectedIndexes[selectedIndexes.length - 1]
        : selectedIndexes[0],
    );
  };

  const canEdit = authContext.user?.id === workout.user.id;

  return (
    <>
      <PohRow>
        <PohCol sm={12}>
          <input
            style={{ width: '100%' }}
            type={InputTypes.range}
            min={0}
            max={workout.track.length}
            step={1}
            onChange={(e) => {
              const i = (e.target as HTMLInputElement).valueAsNumber;
              const trackItem = workout.track[i];
              activePoint.current.setLatLng(trackItem.point);
              mapRef.current?.panTo(trackItem.point);
              scrollToPointByIndex(i);
            }}
            ref={rangeRef}
            list="tickmarks"
          />

          <datalist id="tickmarks" className="d-block w-100" style={{ position: 'relative' }}>
            {Object.entries(
              workout.track.reduce<Record<string, { index: number; width: number }>>(
                (acc, v, i) => {
                  if (!acc[v.date.getHours()])
                    acc[v.date.getHours()] = { index: i, width: (i / workout.track.length) * 100 };
                  return acc;
                },
                {},
              ),
            ).map(([k, v], i) => {
              if (i === 0) return null;
              return (
                <option
                  key={k}
                  value={v.index}
                  style={{
                    width: `${v.width}%`,
                    position: 'absolute',
                    left: 8,
                    textAlign: 'right',
                    fontSize: 10,
                  }}
                  label={k}
                >
                  <small>{k}</small>
                </option>
              );
            })}
          </datalist>

          <br />
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol sm={8}>
          <div ref={mapContainerRef} style={{ height: '600px', outline: '1px dotted tomato' }} />
        </PohCol>
        <PohCol sm={2} className="d-flex flex-column" style={{ height: '600px' }}>
          <div className="d-flex justify-content-between">Точки</div>
          <div style={{ overflowY: 'scroll', userSelect: 'none', flexGrow: 2 }}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>
                    T<sub>сут.</sub>
                  </th>
                  <th>V,км/ч</th>
                  <th>S,км</th>
                  <th>H,м</th>
                  <th>*</th>
                </tr>
              </thead>
              <tbody ref={listRef}>
                {workout.track.map((trackItem, i, allPoints) => {
                  const distance =
                    i == 0
                      ? 0
                      : getDistanceBetweenPointsInMeters(
                          allPoints[i - 1].point as [number, number],
                          trackItem.point as [number, number],
                        );
                  const secs =
                    i == 0
                      ? 0
                      : (trackItem.date.getTime() - allPoints[i - 1].date.getTime()) / 1000;

                  const speed = distance / secs;

                  distInc += distance;

                  const green = 255 * (speed / (total.speed * 2));
                  const red = 255 - 255 * (speed / total.speed);
                  const blue = 100;

                  return (
                    <tr
                      key={trackItem.date.toISOString()}
                      id={`track-point-${i}`}
                      onMouseMove={() => {
                        activePoint.current.setLatLng(trackItem.point);
                        mapRef.current?.panTo(trackItem.point);
                      }}
                      onClick={(e) => {
                        if (canEdit) {
                          if (e.shiftKey || selectedIndexes.length === 1) {
                            e.preventDefault();
                            e.stopPropagation();
                            setSelectedIndexes((cur) => {
                              const arr = [];
                              let inc = cur[0];
                              while (inc <= i) {
                                arr.push(inc);
                                inc++;
                              }
                              return arr;
                            });
                            return;
                          }
                          setSelectedIndexes([i]);
                        }
                        scrollToPointByIndex(i);
                      }}
                      style={{
                        backgroundColor: selectedIndexes.includes(i) ? 'lightyellow' : '',
                        lineHeight: 1,
                        color: `rgb(${red},${green}, ${blue})`,
                      }}
                    >
                      <td>{trackItem.date.toLocaleTimeString()}</td>
                      <td>{i > 0 ? (speed * 3.6).toFixed(1) : '-'}</td>
                      <td>{(distInc / 1000).toFixed(2)}</td>
                      <td>{Math.round(trackItem.point[2] ?? 0)}</td>
                      <td>{indexMarkupsMap[i]?.name ?? ''}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          <div className="bg-light p-2 border-top">
            {selectedIndexes.length === 1 && <div>Выберите вторую точку</div>}
            {selectedIndexes.length > 0 && (
              <div>
                {selectedIndexes.length > 1 && (
                  <WorkoutTrackMarkupSelected
                    trackPoints={workout.track.filter((_, i) => selectedIndexes.includes(i))}
                  />
                )}
                <div className="d-flex align-items-center justify-content-between">
                  <div>
                    <PohButton
                      size={ButtonSize.Small}
                      onClick={() => changeSelection('addStart')}
                      icon={IconsEnum.chevron_up}
                    />
                    <PohButton
                      size={ButtonSize.Small}
                      disabled={selectedIndexes.length === 1}
                      onClick={() => changeSelection('removeStart')}
                      icon={IconsEnum.chevron_down}
                    />
                  </div>
                  <div>
                    <PohButton
                      size={ButtonSize.Small}
                      onClick={() => {
                        setSelectedIndexes([]);
                      }}
                      icon={IconsEnum.close}
                    />
                    &nbsp;
                    {selectedIndexes.length > 1 && (
                      <PohButton
                        size={ButtonSize.Small}
                        variant={ButtonVariant.Success}
                        onClick={async (e) => {
                          const btn = e.target as HTMLButtonElement;
                          btn.disabled = true;
                          if (currentMarkup) {
                            await handleSaveExist();
                          } else {
                            await handleSaveNew({ isBreak: !e.altKey });
                          }
                          btn.disabled = false;
                        }}
                        icon={IconsEnum.save}
                      />
                    )}
                  </div>
                  <div>
                    <PohButton
                      size={ButtonSize.Small}
                      disabled={selectedIndexes.length === 1}
                      onClick={() => changeSelection('removeEnd')}
                      icon={IconsEnum.chevron_up}
                    />
                    <PohButton
                      size={ButtonSize.Small}
                      onClick={() => changeSelection('addEnd')}
                      icon={IconsEnum.chevron_down}
                    />
                  </div>
                </div>
              </div>
            )}
          </div>
        </PohCol>
        <PohCol sm={2}>
          <div>Разметка</div>
          {markups?.length > 0 && (
            <PohList
              data={markups.map((markup) => ({
                key: markup.id,
                action: true,
                content: (
                  <WorkoutTrackMarkupItem
                    markup={markup}
                    onDelete={
                      !canEdit
                        ? undefined
                        : async (e) => {
                            const btn = e.target as HTMLButtonElement;
                            btn.disabled = true;
                            const ok = await confirmModal({
                              title: `Удаление ${markup.isBreak ? 'привала' : 'участка'}`,
                              children: `Хотите безвозвратно удалить ${markup.name}?`,
                            });

                            if (ok) {
                              await deleteWorkoutTrackMarkup(markup.id);
                              setMarkups(markups.filter((x) => x.id !== markup.id));
                              notificationHelper.success('Удалено');
                            }

                            btn.disabled = false;
                          }
                    }
                    onEdit={
                      !canEdit
                        ? undefined
                        : async (e) => {
                            const btn = e.target as HTMLButtonElement;
                            btn.disabled = true;

                            await handleEdit(markup);

                            btn.disabled = false;
                          }
                    }
                  />
                ),
                onClick: () => {
                  if (!mapRef.current) return;
                  const points = workout.track.filter(
                    (p) => p.date >= markup.utcD1 && p.date <= markup.utcD2,
                  );

                  const indexes = workout.track.reduce<number[]>((acc, x, i) => {
                    if (x.date >= markup.utcD1 && x.date <= markup.utcD2) {
                      acc.push(i);
                    }

                    return acc;
                  }, []);
                  scrollToPointByIndex(indexes[0]);

                  activeMarkupPolyline.current.setLatLngs(points.map((x) => x.point));
                  mapRef.current.fitBounds(activeMarkupPolyline.current.getBounds());
                },
              }))}
            />
          )}
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol sm={12}>
          <h3>График движения</h3>
          <WorkoutTrackMarkupTable workout={workout} markups={markups} />
        </PohCol>
      </PohRow>
    </>
  );
};

export default WorkoutMarkupEdit;
